<footer>WastedToken Mint · struck, not printed · every coin is a wasted token well spent</footer>

<script>
(function(){
  "use strict";

  function rotateVec(x,y,z,yaw,pitch){
    const x1 = x*Math.cos(yaw) + z*Math.sin(yaw);
    const z1 = -x*Math.sin(yaw) + z*Math.cos(yaw);
    const y1 = y;
    const y2 = y1*Math.cos(pitch) - z1*Math.sin(pitch);
    const z2 = y1*Math.sin(pitch) + z1*Math.cos(pitch);
    return [x1,y2,z2];
  }

  function embossText(ctx,str,x,y,fillColor){
    ctx.fillStyle='rgba(0,0,0,0.55)';
    ctx.fillText(str,x+0.008,y+0.008);
    ctx.fillStyle='rgba(255,255,255,0.30)';
    ctx.fillText(str,x-0.006,y-0.006);
    ctx.fillStyle=fillColor;
    ctx.fillText(str,x,y);
  }

  function arcText(ctx,text,radius,top,color){
    const n = text.length;
    const totalAngle = Math.min(2.7, n*0.24);
    const start = -totalAngle/2;
    const step = n>1 ? totalAngle/(n-1) : 0;
    ctx.save();
    ctx.font = '700 0.155px Georgia, serif';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    for(let i=0;i<n;i++){
      const a = start + step*i;
      const lx = Math.sin(a)*radius;
      const ly = (top ? Math.cos(a) : -Math.cos(a))*radius;
      ctx.save();
      ctx.translate(lx,ly);
      ctx.rotate(top ? -a : -a + Math.PI);
      embossText(ctx, text[i], 0, 0, color);
      ctx.restore();
    }
    ctx.restore();
  }

  function drawStar(ctx,cx,cy,r,color){
    ctx.save();
    ctx.translate(cx,cy);
    ctx.beginPath();
    for(let i=0;i<5;i++){
      const a = -Math.PI/2 + i*(Math.PI*2/5);
      const a2 = a + Math.PI/5;
      ctx.lineTo(Math.cos(a)*r, Math.sin(a)*r);
      ctx.lineTo(Math.cos(a2)*r*0.45, Math.sin(a2)*r*0.45);
    }
    ctx.closePath();
    ctx.fillStyle=color;
    ctx.fill();
    ctx.restore();
  }

  function drawLaurel(ctx,side,color){
    ctx.save();
    ctx.strokeStyle=color; ctx.fillStyle=color; ctx.lineWidth=0.012;
    ctx.globalAlpha=0.9;
    ctx.beginPath();
    ctx.moveTo(side*0.60, 0.42);
    ctx.quadraticCurveTo(side*0.72, -0.02, side*0.48, -0.42);
    ctx.stroke();
    for(let i=0;i<7;i++){
      const tt = i/6;
      const x = side*(0.60 + (0.48-0.60)*tt);
      const y = 0.42 + (-0.42-0.42)*tt;
      ctx.save();
      ctx.translate(x,y);
      ctx.rotate(side*(1.0 - tt*0.7));
      ctx.beginPath();
      ctx.ellipse(0,0,0.10,0.038,0,0,Math.PI*2);
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();
  }

  function drawFront(ctx,opt){
    arcText(ctx, opt.frontTitle, 0.74, true, opt.palette.text);
    arcText(ctx, opt.frontSub, 0.74, false, opt.palette.text);
    ctx.save();
    ctx.lineWidth=0.02;
    ctx.strokeStyle=opt.palette.lineDark;
    ctx.fillStyle=opt.palette.emblemFill;
    ctx.beginPath();
    ctx.moveTo(0,-0.42);
    ctx.quadraticCurveTo(0.32,-0.34,0.32,-0.05);
    ctx.quadraticCurveTo(0.32,0.28,0,0.44);
    ctx.quadraticCurveTo(-0.32,0.28,-0.32,-0.05);
    ctx.quadraticCurveTo(-0.32,-0.34,0,-0.42);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.font='700 0.5px Georgia, serif';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    embossText(ctx, opt.monogram, 0, 0.01, opt.palette.text);
    drawStar(ctx,-0.58,0,0.05,opt.palette.text);
    drawStar(ctx,0.58,0,0.05,opt.palette.text);
    ctx.restore();
  }

  function drawBack(ctx,opt){
    drawLaurel(ctx,-1,opt.palette.text);
    drawLaurel(ctx,1,opt.palette.text);
    ctx.save();
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.font='700 0.32px Georgia, serif';
    embossText(ctx, opt.backNumber, 0, -0.06, opt.palette.text);
    ctx.font='700 0.12px Georgia, serif';
    embossText(ctx, opt.backLabel, 0, 0.22, opt.palette.text);
    ctx.restore();
  }

  function renderCoin(ctx,size,t,opt){
    const cx=size/2, cy=size/2;
    const scale = size*0.27;
    const yaw = t*Math.PI*2*(opt.spins||1);
    const pitch = t*Math.PI*2*(opt.flips||2);

    const ex = rotateVec(1,0,0,yaw,pitch);
    const ey = rotateVec(0,1,0,yaw,pitch);
    const ez = rotateVec(0,0,1,yaw,pitch);
    const fz = ez[2];
    let bx,by;
    if(fz>=0){ bx=ex; by=ey; } else { bx=rotateVec(-1,0,0,yaw,pitch); by=ey; }
    const faceZ = Math.abs(fz);
    const edgeFactor = Math.sqrt(Math.max(0,1-faceZ*faceZ));

    ctx.save();
    ctx.setTransform(bx[0]*scale, -bx[1]*scale, by[0]*scale, -by[1]*scale, cx, cy);

    ctx.beginPath();
    ctx.arc(0,0,1,0,Math.PI*2);
    const grad = ctx.createLinearGradient(-1,-1,1,1);
    grad.addColorStop(0, opt.palette.hi);
    grad.addColorStop(0.5, opt.palette.mid);
    grad.addColorStop(1, opt.palette.lo);
    ctx.fillStyle = grad;
    ctx.fill();

    const rg = ctx.createRadialGradient(-0.3,0.3,0.08, 0,0,1.05);
    rg.addColorStop(0,'rgba(255,255,255,0.30)');
    rg.addColorStop(0.55,'rgba(255,255,255,0)');
    rg.addColorStop(1,'rgba(0,0,0,0.5)');
    ctx.fillStyle = rg;
    ctx.fill();

    if(edgeFactor>0.015){
      ctx.save();
      ctx.beginPath();
      ctx.arc(0,0,0.97,0,Math.PI*2);
      ctx.lineWidth = 0.05 + edgeFactor*0.22;
      ctx.strokeStyle = opt.palette.edge;
      ctx.setLineDash([0.035,0.035]);
      ctx.lineDashOffset = t*4;
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
    }

    ctx.save();
    ctx.beginPath();
    ctx.arc(0,0,0.86,0,Math.PI*2);
    ctx.clip();
    ctx.lineWidth=0.014;
    ctx.strokeStyle=opt.palette.lineDark;
    ctx.beginPath(); ctx.arc(0,0,0.82,0,Math.PI*2); ctx.stroke();
    ctx.beginPath(); ctx.arc(0,0,0.60,0,Math.PI*2); ctx.stroke();

    if(fz>=0){ drawFront(ctx,opt); } else { drawBack(ctx,opt); }
    ctx.restore();

    ctx.save();
    ctx.beginPath();
    ctx.arc(0,0,0.97,0,Math.PI*2);
    ctx.clip();
    const hx = Math.sin(yaw*1.3 + pitch*0.6)*0.9;
    const hy = Math.cos(pitch*1.1)*0.7 - 0.1;
    const hg = ctx.createRadialGradient(hx,hy,0, hx,hy,0.9);
    hg.addColorStop(0,'rgba(255,255,255,0.85)');
    hg.addColorStop(0.25,'rgba(255,255,255,0.22)');
    hg.addColorStop(1,'rgba(255,255,255,0)');
    ctx.globalCompositeOperation='lighter';
    ctx.fillStyle=hg;
    ctx.fillRect(-1.1,-1.1,2.2,2.2);
    ctx.globalCompositeOperation='source-over';
    ctx.restore();

    ctx.restore();
    ctx.setTransform(1,0,0,1,0,0);
  }

  function drawBackdrop(ctx,size,dark){
    ctx.setTransform(1,0,0,1,0,0);
    ctx.clearRect(0,0,size,size);
    const g = ctx.createRadialGradient(size*0.5,size*0.42,size*0.05,size*0.5,size*0.5,size*0.62);
    if(dark){
      g.addColorStop(0,'#2b2620');
      g.addColorStop(1,'#100e0b');
    } else {
      g.addColorStop(0,'#231d17');
      g.addColorStop(1,'#0d0b09');
    }
    ctx.fillStyle=g;
    ctx.fillRect(0,0,size,size);
  }

  function drawBanner(ctx,size,text,color){
    ctx.setTransform(1,0,0,1,0,0);
    ctx.save();
    ctx.translate(size*0.5,size*0.80);
    ctx.rotate(-0.26);
    ctx.fillStyle=color;
    ctx.fillRect(-size*0.62,-size*0.075,size*1.24,size*0.15);
    ctx.strokeStyle='rgba(255,255,255,0.55)';
    ctx.lineWidth=2;
    ctx.strokeRect(-size*0.62,-size*0.075,size*1.24,size*0.15);
    ctx.fillStyle='#f5f0e6';
    ctx.font='700 '+(size*0.068)+'px Georgia, serif';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText(text,0,1);
    ctx.restore();
  }

  const HERO_PALETTE = { hi:'#f6e2a0', mid:'#c99a3f', lo:'#5c3f14', edge:'#3c2a10',
    lineDark:'rgba(40,25,5,0.6)', text:'#2a1b06', emblemFill:'#d8ad55' };
  const HERO_OPT = {
    spins:1, flips:2, palette:HERO_PALETTE,
    frontTitle:'WASTEDTOKEN MINT', frontSub:'CHALLENGE COIN', monogram:'W',
    backNumber:'10,000', backLabel:'TOKENS'
  };

  const heroCanvas = document.getElementById('coin-hero');
  const heroCtx = heroCanvas.getContext('2d');
  const HERO_SIZE = heroCanvas.width;
  const LOOP_MS = 6000;
  let heroPaused = false;
  let heroRAF = null;
  let startTime = null;

  function renderHeroAtT(t){
    const tt = ((t % 1) + 1) % 1;
    drawBackdrop(heroCtx, HERO_SIZE, true);
    renderCoin(heroCtx, HERO_SIZE, tt, HERO_OPT);
  }

  function heroLoop(ts){
    if(heroPaused) return;
    if(startTime===null) startTime = ts;
    const elapsed = (ts - startTime) % LOOP_MS;
    renderHeroAtT(elapsed / LOOP_MS);
    heroRAF = requestAnimationFrame(heroLoop);
  }
  heroRAF = requestAnimationFrame(heroLoop);

  window.demo = {
    canvas: heroCanvas,
    setTime: function(t){
      heroPaused = true;
      if(heroRAF){ cancelAnimationFrame(heroRAF); heroRAF = null; }
      renderHeroAtT(t);
    },
    pause: function(){
      heroPaused = true;
      if(heroRAF){ cancelAnimationFrame(heroRAF); heroRAF = null; }
    }
  };

  const PALETTES = {
    bronze: { hi:'#eec190', mid:'#a86a35', lo:'#432608', edge:'#2e1a09', lineDark:'rgba(40,20,5,0.6)', text:'#2a1508', emblemFill:'#c6863f' },
    silver: { hi:'#ffffff', mid:'#c3c9cf', lo:'#565c62', edge:'#3a3e42', lineDark:'rgba(20,25,30,0.55)', text:'#202427', emblemFill:'#d8dde1' },
    gold:   { hi:'#fff3b0', mid:'#e0b02c', lo:'#5f4004', edge:'#3d2a03', lineDark:'rgba(40,25,0,0.6)', text:'#3a2603', emblemFill:'#f0c94a' },
    black:  { hi:'#7a7a88', mid:'#232228', lo:'#000000', edge:'#000000', lineDark:'rgba(0,0,0,0.7)', text:'#d8d8e6', emblemFill:'#3a3a44' }
  };

  const EDITION_DATA = [
    { key:'bronze', state:'available',   tokens:'1,000',  monogram:'B' },
    { key:'silver', state:'available',   tokens:'5,000',  monogram:'S' },
    { key:'gold',   state:'sold-out',    tokens:'10,000', monogram:'G' },
    { key:'black',  state:'coming-soon', tokens:'25,000', monogram:'O' }
  ];

  document.querySelectorAll('.edition').forEach(function(tile, i){
    const key = tile.getAttribute('data-edition');
    const data = EDITION_DATA.find(function(d){ return d.key===key; });
    if(!data) return;
    const canvas = tile.querySelector('.edition-canvas');
    const SIZE = 340;
    canvas.width = SIZE; canvas.height = SIZE;
    const ctx = canvas.getContext('2d');
    const opt = {
      spins:1, flips:2, palette: PALETTES[key],
      frontTitle:'WASTEDTOKEN MINT', frontSub: key.toUpperCase()+' EDITION',
      monogram: data.monogram, backNumber: data.tokens, backLabel:'TOKENS'
    };
    const phase = i*0.17;
    let raf=null;
    function loop(ts){
      const t = (((ts/6000) + phase) % 1 + 1) % 1;
      drawBackdrop(ctx, SIZE, key==='black');
      renderCoin(ctx, SIZE, t, opt);
      if(data.state==='sold-out'){ drawBanner(ctx, SIZE, 'SOLD OUT', 'rgba(110,15,15,0.92)'); }
      if(data.state==='coming-soon'){ drawBanner(ctx, SIZE, 'COMING WINTER', 'rgba(15,15,30,0.92)'); }
      raf = requestAnimationFrame(loop);
    }
    raf = requestAnimationFrame(loop);
  });

})();
</script>
